export type MtrErrors = {
  /**
   * Invalid URL.
   */
  400: BaseErrorResponseDto;
  /**
   * MTR is not installed.
   */
  500: BaseErrorResponseDto;
};

export type MtrError = MtrErrors[keyof MtrErrors];

export type MtrResponses = {
  /**
   * MTR test completed successfully
   */
  200: MtrResponseDto;
};

export type MtrResponse = MtrResponses[keyof MtrResponses];

export type PingData = {
  body: PingDto;
  path?: never;
  query?: never;
  url: "/ping";
};

export type PingErrors = {
  /**
   * Invalid URL.
   */
  400: BaseErrorResponseDto;
  /**
   * Host is unreachable.
   */
  504: BaseErrorResponseDto;
};

export type PingError = PingErrors[keyof PingErrors];

export type PingResponses = {
  /**
   * Ping test completed successfully
   */
  200: PingResponseDto;
};

export type PingResponse = PingResponses[keyof PingResponses];

export type LighthouseData = {
  body: LighthouseDto;
  path?: never;
  query?: never;
  url: "/lighthouse";
};

export type LighthouseErrors = {
  /**
   * Invalid URL.
   */
  400: BaseErrorResponseDto;
  /**
   * Unable to connect to the target website.
   */
  422: BaseErrorResponseDto;
  /**
   * Lighthouse audit failed.
   */
  500: BaseErrorResponseDto;
};

export type LighthouseError = LighthouseErrors[keyof LighthouseErrors];

export type LighthouseResponses = {
  /**
   * Successfully ran Lighthouse audit
   */
  200: LighthouseResponseDto;
};

export type LighthouseResponse = LighthouseResponses[keyof LighthouseResponses];

export type SearchData = {
  body: SearchRequestDto;
  path?: never;
  query?: never;
  url: "/search";
};

export type SearchErrors = {
  /**
   * Invalid URL.
   */
  400: BaseErrorResponseDto;
  /**
   * Unable to connect to the target website.
   */
  422: BaseErrorResponseDto;
  /**
   * Search failed.
   */
  500: BaseErrorResponseDto;
};

export type SearchError = SearchErrors[keyof SearchErrors];

export type SearchResponses = {
  /**
   * Search results (format depends on request)
   */
  200:
    | SearchResponseDto
    | ImageSearchResponseDto
    | SearchMarkdownResponseDto
    | SearchHtmlResponseDto
    | GroundedAnswerResponseDto;
};

export type SearchResponse = SearchResponses[keyof SearchResponses];
